"""ms — sira_c."""

T = {
"sira_151": ("Bapa saudara Nabi ﷺ yang manakah memeluk Islam dan menjadi antara pembelanya yang paling gigih di Makkah?", ["Hamzah bin 'Abd al-Muttalib", "Abu Lahab", "Abu Talib", "Al-'Abbas"], "Hamzah, bapa saudara sekaligus saudara susuan Nabi ﷺ, memeluk Islam di Makkah dan digelar «singa Allah»."),
"sira_152": ("Di rumah siapakah orang Islam pertama bertemu secara rahsia di Makkah?", ["Rumah al-Arqam", "Rumah Abu Bakar", "Rumah Khadijah", "Rumah Abu Talib"], "Rumah al-Arqam bin Abi al-Arqam, di bukit Safa, ialah tempat perhimpunan dan pengajaran yang pertama."),
"sira_153": ("Sahabat manakah, yang memeluk Islam di Makkah, kemudian diutus sebagai guru pertama ke Yathrib?", ["Mus'ab bin 'Umair", "Bilal bin Rabah", "Khalid bin al-Walid", "Abu Hurairah"], "Mus'ab bin 'Umair, pemuda Makkah daripada keluarga bangsawan, diutus ke Yathrib selepas Bai'ah 'Aqabah untuk mengajar al-Quran."),
"sira_154": ("Dengan perintah apakah Surah al-Muddaththir, yang memulakan dakwah terbuka, dibuka?", ["«Wahai orang yang berselimut! Bangunlah dan berilah peringatan»", "«Bacalah, dengan nama Tuhanmu»", "«Perangilah orang kafir»", "«Berhijrahlah ke Madinah»"], "«Wahai orang yang berselimut! Bangunlah, lalu berilah peringatan.»"),
"sira_155": ("Ayat manakah yang memerintahkan Nabi ﷺ menyampaikan secara terbuka apa yang diperintahkan kepadanya?", ["«Maka sampaikanlah secara terang-terangan apa yang diperintahkan kepadamu»", "«Bersabarlah»", "«Bacalah secara rahsia»", "«Berundurlah»"], "«Maka sampaikanlah secara terang-terangan apa yang diperintahkan kepadamu, dan berpalinglah daripada orang musyrik.»"),
"sira_156": ("Di manakah Quraisy menggantung dokumen pemulauan terhadap Bani Hasyim?", ["Di dalam Kaabah", "Di pintu kota", "Di pasar 'Ukaz", "Di bukit Safa"], "Teks pemulauan itu digantung di dalam Kaabah, sehinggalah perjanjian itu dibatalkan dan dokumen itu ditinggalkan."),
"sira_157": ("Di kebun siapakah di Taif Nabi ﷺ berteduh dan menerima setandan anggur setelah dihalau?", ["Kebun 'Utbah dan Syaibah, tempat hamba 'Addas melayaninya", "Rumah ketua Taif", "Sebuah kafilah yang lalu", "Rumah seorang tukang besi"], "Setelah dicederakan dan dihalau dari Taif, baginda berteduh di sebuah kebun dan dihidangkan anggur, dibawa oleh seorang hamba Kristian bernama 'Addas."),
"sira_158": ("Sahabat manakah, yang pada mulanya penentang keras, memeluk Islam dan digelar «pembeza antara yang benar dan yang batil»?", ["'Umar bin al-Khattab", "Abu Sufyan", "Khalid bin al-Walid", "'Amr bin al-'As"], "'Umar bin al-Khattab, yang pada mulanya memusuhi, memeluk Islam di Makkah dan diberi gelaran al-Faruq."),
"sira_159": ("Bersama keluarga manakah Nabi ﷺ tinggal ketika sampai di Madinah, tempat untanya berhenti?", ["Bersama Abu Ayyub al-Ansari", "Bersama Sa'd bin Mu'adz", "Bersama Ubay bin Ka'ab", "Bersama Anas bin Malik"], "Unta itu berhenti berhampiran rumah Abu Ayyub al-Ansari, yang menerima Nabi ﷺ ketika ketibaannya."),
"sira_160": ("Apakah nama tanah perkuburan Madinah, tempat ramai sahabat dimakamkan?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hijr", "Al-Quba"], "Baqi' al-Gharqad, di sebelah masjid Nabi ﷺ, ialah tanah perkuburan Madinah."),
"sira_161": ("Masjid manakah yang digambarkan al-Quran sebagai «didirikan atas dasar takwa sejak hari pertama»?", ["Masjid Quba", "Masjidil Haram", "Masjid al-Aqsa", "Masjid Kufah"], "«Sesungguhnya masjid yang didirikan atas dasar takwa sejak hari pertama lebih berhak engkau bersolat di dalamnya.»"),
"sira_162": ("Di masjid manakah Nabi ﷺ sedang bersolat ketika perintah menukar kiblat diturunkan?", ["Masjid dua kiblat (Masjid al-Qiblatain)", "Masjid Quba", "Masjidil Haram", "Masjid al-Aqsa"], "Perintah itu datang ketika solat; para jemaah berpaling ke arah Kaabah, maka masjid itu dinamakan «masjid dua kiblat»."),
"sira_163": ("Kewajipan manakah yang disyariatkan kepada orang Islam pada tahun kedua Hijrah?", ["Puasa bulan Ramadan", "Haji", "Solat malam", "Perjalanan ke Taif"], "Puasa Ramadan diwajibkan di Madinah, pada tahun kedua selepas Hijrah."),
"sira_164": ("Sahabat manakah yang melihat lafaz azan dalam mimpi, lalu diterima pakai oleh Nabi ﷺ?", ["'Abdullah bin Zaid", "Bilal bin Rabah", "Abu Bakar", "Mu'adz bin Jabal"], "'Abdullah bin Zaid menceritakan mimpi azan itu; Nabi ﷺ memperakuinya dan menyuruh Bilal melaungkannya."),
"sira_165": ("Apakah yang dikatakan al-Quran tentang segenggam debu yang dilempar Nabi ﷺ di Badar?", ["«Bukan engkau yang melempar ketika engkau melempar, tetapi Allah yang melempar»", "«Engkau membidik dengan tepat»", "«Angin membawanya»", "«Malaikat yang melemparnya»"], "«Dan bukan engkau yang melempar ketika engkau melempar, tetapi Allah yang melempar.»"),
"sira_166": ("Bagaimanakah al-Quran menggambarkan keadaan sebahagian orang beriman ketika keluar ke Badar?", ["Mereka membantah tentangnya seolah-olah digiring kepada kematian", "Mereka semua bersemangat", "Mereka enggan keluar", "Mereka meminta penangguhan"], "«Mereka membantahmu tentang kebenaran setelah nyata, seolah-olah mereka digiring kepada kematian.»"),
"sira_167": ("Bagaimanakah al-Quran mengingatkan orang beriman tentang keadaan mereka sebelum kemenangan?", ["Mereka sedikit lagi tertindas di bumi, lalu Allah melindungi dan menolong mereka", "Mereka kaya", "Mereka ramai", "Mereka sudah memerintah"], "«Dan ingatlah ketika kamu masih sedikit lagi tertindas di bumi… lalu Dia melindungi kamu dan menguatkan kamu dengan pertolongan-Nya.»"),
"sira_168": ("Sahabat manakah di Badar yang mencadangkan agar tentera berpindah ke telaga yang paling hampir dengan musuh?", ["Al-Hubab bin al-Mundzir", "Sa'd bin Mu'adz", "Al-Miqdad", "Az-Zubair"], "Al-Hubab bin al-Mundzir bertanya sama ada kedudukan itu wahyu atau pendapat; setelah diberitahu ia pendapat, dia mencadangkan maju ke telaga, dan Nabi ﷺ bersetuju."),
"sira_169": ("Apakah nama tempat pengairan yang menjadi tempat berlakunya peperangan Badar?", ["Badar, sebuah telaga di jalan kafilah", "Zamzam", "Quba", "Al-Hudaibiyah"], "Badar ialah tempat pengairan di jalan kafilah antara Makkah dan Syam; peperangan itu mengambil namanya."),
"sira_170": ("Perkara apakah tentang tawanan yang dijelaskan melalui wahyu selepas Badar?", ["Tebusan yang diterima bagi para tawanan", "Pembahagian air", "Pemilihan tempat berkhemah", "Tarikh pulang"], "Petikan itu membicarakan tawanan dan tebusan, kemudian menghalalkan apa yang telah diambil sebagai baik dan halal."),
"sira_171": ("Menurut Surah Ali 'Imran, apakah yang mengubah keadaan di Uhud selepas kejayaan awal?", ["Kederhakaan dan pertikaian tentang perintah yang diberikan", "Bilangan musuh", "Kepanasan", "Kekurangan air"], "«…sehingga kamu lemah dan berselisih tentang urusan itu serta menderhakai perintah.»"),
"sira_172": ("Apakah yang dikatakan al-Quran tentang mereka yang terbunuh di jalan Allah?", ["Jangan sangka mereka mati: mereka hidup di sisi Tuhan mereka", "Mereka tidur sehingga Hari Kiamat", "Mereka kembali", "Mereka dilupakan"], "«Dan jangan sekali-kali kamu menyangka orang yang terbunuh di jalan Allah itu mati. Bahkan mereka hidup di sisi Tuhan mereka dengan mendapat rezeki.»"),
"sira_173": ("Di bukit manakah Nabi ﷺ menempatkan para pemanah di Uhud?", ["Bukit Pemanah (Jabal ar-Rumat)", "Bukit Safa", "Gunung Thur", "Gunung Hira"], "Lima puluh pemanah ditempatkan di sebuah bukit yang kemudian dinamakan «bukit pemanah», dengan arahan agar tidak meninggalkannya."),
"sira_174": ("Bagaimanakah Surah al-Ahzab menggambarkan ujian pengepungan Madinah?", ["Mata terbeliak, hati naik sampai ke kerongkong", "Kota itu jatuh", "Hanya makanan yang kekurangan", "Langit menjadi gelap"], "«Ketika mereka datang kepadamu dari atas dan dari bawah kamu, dan ketika mata terbeliak dan hati naik sampai ke kerongkong.»"),
"sira_175": ("Bagaimanakah al-Quran menggambarkan kesudahan Perang Khandaq?", ["Allah menghalau kembali golongan bersekutu itu dalam kemarahan mereka, tanpa memperoleh apa-apa kebaikan", "Pertempuran panjang", "Satu perjanjian damai", "Pengunduran orang Islam"], "«Dan Allah menghalau orang kafir itu dalam keadaan marah, mereka tidak memperoleh apa-apa kebaikan. Dan cukuplah Allah bagi orang beriman dalam peperangan.»"),
"sira_176": ("Di manakah Hudaibiyah, tempat perjanjian yang masyhur itu?", ["Di pinggir tanah haram, di sebelah barat Makkah", "Berhampiran Madinah", "Di Yaman", "Di Syam"], "Hudaibiyah ialah tempat di pinggir tanah haram Makkah, tempat perjanjian itu dimeterai."),
"sira_177": ("Mimpi Nabi ﷺ yang manakah disahkan al-Quran selepas Hudaibiyah?", ["Bahawa mereka akan memasuki Masjidil Haram dengan aman, mencukur atau memendekkan rambut", "Bahawa mereka akan menang di Khaibar", "Bahawa mereka akan membina sebuah kota", "Bahawa mereka akan ke Syam"], "«Sesungguhnya Allah telah membuktikan kepada Rasul-Nya mimpi itu dengan benar: kamu pasti akan memasuki Masjidil Haram dengan aman.»"),
"sira_178": ("Apakah yang diingatkan Surah al-Fath tentang tangan yang ditahan di Makkah?", ["Allah menahan tangan mereka daripada kamu dan tangan kamu daripada mereka di dalam Makkah", "Dia memerintahkan peperangan", "Dia menutup jalan", "Dia menghantar ribut"], "«Dan Dialah yang menahan tangan mereka daripada kamu dan tangan kamu daripada mereka di lembah Makkah, setelah Dia memenangkan kamu atas mereka.»"),
"sira_179": ("Pada tahun Hijrah keberapakah berlaku ekspedisi Khaibar?", ["Ketujuh", "Kedua", "Kelima", "Kesepuluh"], "Khaibar berlaku pada tahun 7 Hijrah, setahun selepas perjanjian Hudaibiyah."),
"sira_180": ("Apakah nama umrah yang dilakukan setahun selepas Hudaibiyah, menurut syarat perjanjian itu?", ["'Umrah al-Qada'", "Hijjah al-Wada'", "'Umrah al-Ji'ranah", "Al-Hajj al-Akbar"], "Perjanjian itu menetapkan orang Islam akan kembali pada tahun berikutnya; umrah itu dinamakan 'umrah al-qada'."),
"sira_181": ("Pemerintah manakah yang mengoyakkan surat Nabi ﷺ ketika menerimanya?", ["Raja Parsi (Kisra)", "Najasyi Habsyah", "Gabenor Bahrain", "Raja Yaman"], "Nabi ﷺ mengirim surat kepada raja-raja jiran; surat kepada raja Parsi telah dikoyakkan."),
"sira_182": ("Sahabat manakah yang diutus membawa surat Nabi ﷺ kepada Najasyi Habsyah dan kepada pemerintah lain?", ["'Amr bin Umayyah ad-Damri", "Abu Hurairah", "Anas bin Malik", "Ubay bin Ka'ab"], "Utusan dipilih daripada kalangan sahabat; 'Amr bin Umayyah ad-Damri diutus kepada Najasyi."),
"sira_183": ("Di arah manakah Khaibar terletak dari Madinah?", ["Di utara", "Di selatan", "Di timur", "Di barat, di tepi laut"], "Khaibar ialah oasis berkubu di utara Madinah, di jalan menuju Syam."),
"sira_184": ("Apakah yang menjadi rumah Abu Sufyan pada hari pembukaan Makkah?", ["Tempat aman bagi sesiapa yang memasukinya", "Sebuah penjara", "Sebuah gudang", "Sebuah masjid"], "Nabi ﷺ mengisytiharkan keamanan bagi sesiapa yang memasuki Masjidil Haram, tinggal di rumahnya sendiri, atau memasuki rumah Abu Sufyan."),
"sira_185": ("Tahun manakah yang dinamakan «tahun pembukaan» ('am al-fath)?", ["Tahun 8 Hijrah", "Tahun 6 Hijrah", "Tahun 10 Hijrah", "Tahun 2 Hijrah"], "Makkah dibuka pada tahun 8 Hijrah, tahun yang dikenali sebagai «tahun pembukaan»."),
"sira_186": ("Peperangan manakah yang berlaku tidak lama selepas pembukaan Makkah, menentang kabilah Hawazin?", ["Hunain", "Badar", "Uhud", "Khaibar"], "Hunain berlaku tidak lama selepas pembukaan Makkah, di sebuah lembah antara Makkah dan Taif."),
"sira_187": ("Apakah yang diturunkan Allah kepada Rasul-Nya ﷺ dan orang beriman selepas kegusaran mereka di Hunain?", ["Ketenangan-Nya (sakinah), dan tentera yang tidak mereka lihat", "Hujan", "Angin", "Sepasukan berkuda"], "«Kemudian Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang beriman, serta menurunkan tentera yang tidak kamu lihat.»"),
"sira_188": ("Ke kota manakah tentera Islam bergerak selepas Hunain?", ["Taif", "Khaibar", "Tabuk", "Sanaa"], "Selepas Hunain, orang Islam mengepung Taif, yang penduduknya berkurung di dalamnya."),
"sira_189": ("Ekspedisi manakah yang disebut al-Quran sebagai «saat kesukaran» (sa'at al-'usrah)?", ["Tabuk", "Badar", "Khaibar", "Hunain"], "«Sesungguhnya Allah telah menerima taubat Nabi, kaum Muhajirin dan Ansar yang mengikutinya pada saat kesukaran.»"),
"sira_190": ("Apakah yang dikatakan al-Quran tentang tiga sahabat yang tertinggal di Tabuk, sebelum mereka diampunkan?", ["Bumi terasa sempit bagi mereka walaupun luas, kemudian Allah menerima taubat mereka", "Mereka dibuang negeri", "Mereka pergi ke Yaman", "Mereka dilupakan"], "«Dan terhadap tiga orang yang ditinggalkan, sehingga bumi terasa sempit bagi mereka walaupun luas… kemudian Dia menerima taubat mereka.»"),
"sira_191": ("Di arah manakah terletaknya Tabuk, matlamat ekspedisi besar yang terakhir?", ["Di utara, ke arah sempadan Syam", "Di selatan, ke arah Yaman", "Di timur, ke arah Iraq", "Di barat, di Laut Merah"], "Tabuk terletak di utara Madinah, di jalan ke Syam; ia ekspedisi besar terakhir Nabi ﷺ."),
"sira_192": ("Sahabat manakah yang melengkapkan sebahagian besar tentera Tabuk dengan hartanya sendiri?", ["'Uthman bin 'Affan", "Sa'd bin Abi Waqqas", "Talhah bin 'Ubaidillah", "Abu Zar"], "'Uthman bin 'Affan menyediakan bahagian besar perlengkapan «tentera kesukaran» (jaisy al-'usrah)."),
"sira_193": ("Sahabat manakah yang pertama melepaskan anak panah di jalan Allah?", ["Sa'd bin Abi Waqqas", "Az-Zubair bin al-'Awwam", "Talhah bin 'Ubaidillah", "Abu 'Ubaidah"], "Sa'd bin Abi Waqqas, antara yang terawal memeluk Islam, dikenali sebagai orang pertama yang melepaskan anak panah di jalan Allah."),
"sira_194": ("Sahabat manakah yang digelar «hawari Rasulullah ﷺ»?", ["Az-Zubair bin al-'Awwam", "Abu Hurairah", "Salman al-Farisi", "Bilal"], "Az-Zubair bin al-'Awwam, sepupu Nabi ﷺ, digelar hawari baginda, penyokong rapatnya."),
"sira_195": ("Sahabat manakah yang diamanahkan dengan pengetahuan tentang orang munafik, lalu digelar «penyimpan rahsia»?", ["Hudzaifah bin al-Yaman", "Abu Musa al-Asy'ari", "'Ammar bin Yasir", "Abu ad-Darda'"], "Hudzaifah bin al-Yaman dikenali sebagai «sahib as-sirr», orang yang dipercayai Nabi ﷺ tentang kaum munafik."),
"sira_196": ("Dari manakah asalnya Salman, yang digelar «al-Farisi», yang mencadangkan parit itu?", ["Dari Parsi", "Dari Yaman", "Dari Habsyah", "Dari Rom"], "Salman, berketurunan Parsi, mencari kebenaran sekian lama sebelum menyertai Nabi ﷺ di Madinah."),
"sira_197": ("Wanita manakah, ibu kepada Anas bin Malik, yang menyerahkan anaknya untuk berkhidmat kepada Nabi ﷺ?", ["Ummu Sulaim", "Ummu Salamah", "Ummu Aiman", "Ummu Habibah"], "Ummu Sulaim daripada kaum Ansar menyerahkan anaknya Anas kepada Nabi ﷺ untuk berkhidmat ketika baginda tiba di Madinah."),
"sira_198": ("Isteri Nabi ﷺ yang manakah terkenal dengan keluasan ilmunya dan meriwayatkan banyak hadis?", ["'Aisyah", "Saudah", "Juwairiyah", "Maimunah"], "'Aisyah, puteri Abu Bakar, antara perawi hadis terbesar dan rujukan dalam ilmu agama."),
"sira_199": ("Isteri Nabi ﷺ yang manakah merupakan sepupunya, dan perkahwinannya disebut dalam Surah al-Ahzab?", ["Zainab binti Jahsy", "Hafsah", "Ummu Salamah", "Safiyyah"], "Perkahwinan dengan Zainab binti Jahsy disebut dalam Surah al-Ahzab (33:37)."),
"sira_200": ("Isteri Nabi ﷺ yang manakah menasihatkan langkah yang meleraikan kebuntuan di Hudaibiyah?", ["Ummu Salamah", "'Aisyah", "Hafsah", "Zainab binti Jahsy"], "Ummu Salamah menasihatkan Nabi ﷺ agar keluar melakukan sembelihan dan bercukur sendiri: para sahabat segera mengikutinya."),
"sira_201": ("Apakah nama penuh Nabi ﷺ, sehingga datuknya?", ["Muhammad bin 'Abdillah bin 'Abd al-Muttalib", "Muhammad bin Abi Talib", "Muhammad bin al-'Abbas", "Muhammad bin Hasyim"], "Baginda ialah Muhammad, anak 'Abdullah, anak 'Abd al-Muttalib, daripada kabilah Quraisy."),
"sira_202": ("Nama lain Nabi ﷺ yang manakah, yang disebut dalam al-Quran oleh 'Isa, bermaksud «yang paling terpuji»?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abu al-Qasim"], "'Isa mengkhabarkan seorang rasul yang akan datang selepasnya «yang namanya Ahmad» (al-Quran 61:6)."),
"sira_203": ("Berapa lamakah al-Quran diturunkan kepada Nabi ﷺ?", ["Kira-kira dua puluh tiga tahun", "Sepuluh tahun", "Empat puluh tahun", "Satu malam sahaja"], "Wahyu berlangsung kira-kira dua puluh tiga tahun: tiga belas tahun di Makkah dan sepuluh tahun di Madinah."),
"sira_204": ("Sahabat manakah lelaki dewasa merdeka yang pertama memeluk Islam?", ["Abu Bakar as-Siddiq", "'Umar bin al-Khattab", "'Uthman bin 'Affan", "Sa'd bin Abi Waqqas"], "Dalam kalangan lelaki dewasa yang merdeka, Abu Bakar yang pertama menyahut seruan Nabi ﷺ."),
"sira_205": ("Kanak-kanak manakah yang pertama memeluk Islam?", ["'Ali bin Abi Talib", "Anas bin Malik", "Usamah bin Zaid", "'Abdullah bin 'Umar"], "'Ali bin Abi Talib, yang dibesarkan dalam rumah tangga Nabi ﷺ, yang pertama beriman dalam kalangan kanak-kanak."),
"sira_206": ("Bekas hamba Nabi ﷺ yang manakah yang pertama memeluk Islam dalam kalangan bekas hamba?", ["Zaid bin Harithah", "Bilal bin Rabah", "Suhaib ar-Rumi", "Salman al-Farisi"], "Zaid bin Harithah, yang dimerdekakan dan dibesarkan seperti anak oleh Nabi ﷺ, yang pertama beriman dalam kalangan bekas hamba."),
"sira_207": ("Ayat manakah yang mengakhiri pengangkatan anak dari segi nasab, dengan menyatakan Nabi ﷺ bukan bapa kepada mana-mana lelaki mereka?", ["«Muhammad bukanlah bapa kepada seseorang lelaki antara kamu, tetapi dia Rasul Allah dan penutup para nabi»", "«Panggillah mereka dengan nama bapa mereka»", "«Pertalian darah didahulukan»", "«Jangan mengambil anak angkat»"], "«Muhammad bukanlah bapa kepada seseorang lelaki antara kamu, tetapi dia Rasul Allah dan penutup para nabi.»"),
"sira_208": ("Pada hari apakah dalam seminggu orang Islam berhimpun untuk solat berjemaah yang disyariatkan di Madinah?", ["Jumaat", "Sabtu", "Ahad", "Isnin"], "Solat Jumaat disyariatkan di Madinah dan menghimpunkan masyarakat setiap minggu."),
"sira_209": ("Sahabat manakah yang mengimamkan solat semasa sakit terakhir Nabi ﷺ, atas perintah baginda sendiri?", ["Abu Bakar as-Siddiq", "'Umar bin al-Khattab", "'Ali bin Abi Talib", "Bilal"], "Nabi ﷺ memerintahkan agar Abu Bakar mengimamkan solat semasa sakitnya; para sahabat menganggapnya satu petunjuk."),
"sira_210": ("Khalifah manakah yang ditikam ketika mengimamkan solat subuh?", ["'Umar bin al-Khattab", "Abu Bakar", "'Ali bin Abi Talib", "Mu'awiyah"], "'Umar bin al-Khattab ditikam semasa solat fajar di Madinah dan meninggal dunia akibat lukanya."),
"sira_211": ("Berapa lamakah pemerintahan khalifah Abu Bakar?", ["Kira-kira dua tahun", "Sepuluh tahun", "Dua puluh tahun", "Tiga puluh tahun"], "Abu Bakar memerintah kira-kira dua tahun sebelum wafat, dan 'Umar menggantikannya."),
"sira_212": ("Gerakan manakah yang terpaksa ditangani Abu Bakar pada awal pemerintahannya?", ["Keengganan membayar zakat dan kemurtadan sebahagian kabilah", "Serangan dari Parsi", "Kebuluran", "Pemberontakan di Madinah"], "Pemerintahan pertama dibuka dengan perang riddah, terhadap kabilah yang enggan berzakat atau keluar daripada Islam."),
"sira_213": ("Gelaran manakah yang diambil 'Umar bin al-Khattab sebagai ketua umat?", ["Amirul Mukminin (ketua orang beriman)", "Sultan", "Malik", "Imam al-Haramain"], "Gelaran amirul mukminin ditetapkan pada zaman 'Umar dan dipakai oleh khalifah selepasnya."),
"sira_214": ("Masjid manakah di Baitulmaqdis yang menjadi kiblat pertama orang Islam?", ["Masjid al-Aqsa", "Masjid Quba", "Masjid Nabi ﷺ", "Masjidil Haram"], "Orang Islam pada mulanya bersolat mengadap Baitulmaqdis, sebelum kiblat ditetapkan ke arah Kaabah."),
"sira_215": ("Tiga masjid manakah yang digalakkan secara khusus untuk dikunjungi?", ["Masjidil Haram, masjid Nabi ﷺ dan al-Aqsa", "Quba, al-Aqsa dan Kufah", "Masjidil Haram, Quba dan Damsyik", "Al-Aqsa, Kufah dan Basrah"], "Perjalanan digalakkan secara khusus ke tiga masjid: Masjidil Haram, masjid Nabi ﷺ dan Masjid al-Aqsa."),
"sira_216": ("Di manakah Nabi ﷺ menyampaikan khutbah wida'nya, pada hari 'Arafah?", ["Di lembah 'Uranah, di Gunung 'Arafah", "Di Mina", "Di hadapan Kaabah", "Di Muzdalifah"], "Khutbah wida' disampaikan pada hari 'Arafah, di lembah 'Uranah di kaki Gunung 'Arafah."),
"sira_217": ("Apakah yang diisytiharkan Nabi ﷺ sebagai suci tidak boleh dicerobohi dalam khutbah wida'?", ["Darah, harta dan maruah setiap orang", "Jalan perdagangan", "Telaga Madinah", "Kebun kurma"], "Baginda mengisytiharkan darah, harta dan maruah orang Islam suci, sesuci hari itu, bulan itu dan kota itu."),
"sira_218": ("Apakah yang ditinggalkan Nabi ﷺ kepada umatnya dalam khutbah wida', agar mereka tidak sesat?", ["Kitab Allah", "Sebuah harta", "Sebuah tentera", "Sebuah peta"], "Baginda mengingatkan mereka bahawa baginda meninggalkan sesuatu yang harus dipegang agar tidak sesat: Kitab Allah."),
"sira_219": ("Bulan manakah dalam takwim Islam yang menandakan haji yang dilakukan Nabi ﷺ pada wida'nya?", ["Zulhijjah", "Ramadan", "Muharram", "Rejab"], "Haji wida' berlaku pada bulan Zulhijjah tahun 10 Hijrah."),
"sira_220": ("Siapakah yang memandikan dan mengafankan jenazah Nabi ﷺ selepas kewafatannya?", ["Ahli keluarganya, antaranya 'Ali dan al-'Abbas", "Kaum Ansar sahaja", "Bilal dan Anas", "Penduduk Quba"], "Ahli keluarganya sendiri yang menguruskannya, antaranya 'Ali bin Abi Talib dan bapa saudaranya al-'Abbas."),
"sira_221": ("Pada bulan Hijrah manakah Nabi ﷺ wafat?", ["Rabiulawal", "Ramadan", "Syawal", "Zulkaedah"], "Nabi ﷺ wafat di Madinah pada bulan Rabiulawal, tahun 11 Hijrah."),
"sira_222": ("Ayat manakah yang dibaca Abu Bakar untuk mengingatkan orang ramai bahawa Nabi ﷺ seorang manusia?", ["«Muhammad hanyalah seorang rasul; sebelumnya telah berlalu beberapa rasul»", "«Kami mengutusmu sebagai rahmat»", "«Sesungguhnya engkau berbudi pekerti agung»", "«Apabila datang pertolongan Allah»"], "«Muhammad hanyalah seorang rasul. Sebelumnya telah berlalu beberapa rasul. Apakah jika dia wafat atau dibunuh, kamu akan berpaling ke belakang?»"),
"sira_223": ("Sahabat manakah yang paling dikenali kerana banyaknya hadis yang dihafalnya?", ["Abu Hurairah", "Anas bin Malik", "Jabir bin 'Abdillah", "Abu Sa'id al-Khudri"], "Abu Hurairah menghabiskan tahun-tahun terakhir Nabi ﷺ di sisinya dan menjadi perawi hadis yang paling banyak."),
"sira_224": ("Sahabat manakah, sepupu Nabi ﷺ, yang menjadi tokoh besar dalam tafsir al-Quran?", ["'Abdullah bin 'Abbas", "'Abdullah bin 'Umar", "'Abdullah bin Mas'ud", "'Abdullah bin az-Zubair"], "'Abdullah bin 'Abbas, yang didoakan Nabi ﷺ agar difahamkan Kitab, menjadi «jurubahasa al-Quran»."),
"sira_225": ("Sahabat manakah yang diutus Nabi ﷺ sebagai gabenor dan hakim ke Yaman, dan wafat muda di Syam?", ["Mu'adz bin Jabal", "Abu 'Ubaidah bin al-Jarrah", "'Amr bin al-'As", "Khalid bin al-Walid"], "Mu'adz bin Jabal, seorang alim dalam kalangan sahabat, diutus ke Yaman dan kemudian wafat di Syam ketika masih muda."),
"sira_226": ("Lembah manakah yang terletak antara dua bukit Safa dan Marwah, yang dilalui semasa haji?", ["Lembah Makkah, di sekeliling Kaabah", "Lembah 'Uranah", "Lembah Mina", "Lembah Badar"], "Safa dan Marwah ialah dua bukit kecil di lembah Makkah, kini berada di dalam Masjidil Haram."),
"sira_227": ("Dua kabilah Arab besar di Madinah yang manakah berperang sebelum kedatangan Nabi ﷺ?", ["Aus dan Khazraj", "Quraisy dan Hawazin", "Thaqif dan Kinanah", "Tamim dan Bakr"], "Aus dan Khazraj, yang lama bermusuhan, bersama-sama membentuk kaum Ansar selepas kedatangan Nabi ﷺ."),
"sira_228": ("Ayat manakah yang mengingatkan kaum Ansar bahawa mereka pernah bermusuhan lalu Allah menyatukan hati mereka?", ["«Kamu dahulu bermusuhan lalu Dia menyatukan hati kamu»", "«Kamu dahulu miskin»", "«Kamu dahulu sedikit»", "«Kamu dahulu sesat»"], "«Dan ingatlah nikmat Allah ke atas kamu: ketika kamu bermusuhan lalu Dia menyatukan hati kamu, maka kamu menjadi bersaudara dengan nikmat-Nya.»"),
"sira_229": ("Bagaimanakah al-Quran memuji kaum Ansar dalam sambutan mereka terhadap kaum Muhajirin?", ["Mereka mengutamakan orang lain daripada diri sendiri, walaupun mereka sendiri berhajat", "Mereka menjual tanah kepada mereka", "Mereka meminjamkan wang", "Mereka menempatkan mereka di luar kota"], "«Dan mereka mengutamakan orang lain daripada diri mereka, walaupun mereka dalam kesusahan. Dan sesiapa yang dipelihara daripada kebakhilan dirinya, merekalah orang yang berjaya.»"),
"sira_230": ("Apakah nama himpunan perkataan, perbuatan dan perakuan Nabi ﷺ?", ["Sunnah", "Al-Quran", "Sirah", "Tafsir"], "Sunnah ialah apa yang dikatakan, dilakukan atau diperakukan Nabi ﷺ; sirah pula ialah riwayat hidupnya."),
"sira_231": ("Apakah nama generasi selepas generasi para sahabat?", ["Tabi'in (para pengikut)", "Ansar", "Muhajirin", "Qurra'"], "Tabi'in ialah mereka yang bertemu para sahabat tanpa pernah melihat Nabi ﷺ."),
"sira_232": ("Apakah nama rangkaian perawi sesebuah hadis?", ["Isnad", "Matan", "Tafsir", "Tajwid"], "Isnad ialah rangkaian penyampaian; matan pula ialah teks hadis itu sendiri."),
"sira_233": ("Dua himpunan hadis manakah yang dianggap paling ketat, digelar «dua Sahih»?", ["Sahih al-Bukhari dan Sahih Muslim", "Sunan Abu Dawud dan at-Tirmizi", "Al-Muwatta' dan al-Musnad", "Sunan an-Nasa'i dan Ibn Majah"], "Sahih al-Bukhari dan Sahih Muslim bersama-sama digelar «dua Sahih» (as-sahihain)."),
"sira_234": ("Di kota manakah terletaknya masjid Nabi ﷺ dan makamnya?", ["Madinah", "Makkah", "Baitulmaqdis", "Taif"], "Masjid Nabi ﷺ dan makamnya terletak di Madinah, kota Hijrah."),
"sira_235": ("Gelaran apakah yang disandang Madinah, merujuk cahaya yang dikaitkan dengannya?", ["Al-Madinah al-Munawwarah (kota bercahaya)", "Ummul Qura", "Darussalam", "Al-Mada'in"], "Madinah digelar al-Munawwarah; Makkah pula digelar al-Mukarramah."),
"sira_236": ("Nama apakah yang diberikan al-Quran kepada Makkah, «ibu kota-kota»?", ["Ummul Qura", "Al-Madinah", "Al-Balad al-Amin", "Bakkah"], "«…agar engkau memberi peringatan kepada Ummul Qura dan penduduk sekitarnya.»"),
"sira_237": ("Apakah pekerjaan isteri pertama Nabi ﷺ, Khadijah?", ["Peniaga", "Tabib", "Penyair", "Penenun"], "Khadijah binti Khuwailid ialah peniaga yang dihormati di Makkah, yang mengamanahkan kafilahnya kepada Muhammad ﷺ yang masih muda."),
"sira_238": ("Berapa lamakah Nabi ﷺ berkahwin dengan Khadijah seorang sahaja?", ["Sehingga kewafatannya; baginda tidak berkahwin dengan wanita lain semasa hayatnya", "Dua tahun", "Lima tahun", "Baginda terus berkahwin dengan yang lain"], "Nabi ﷺ tidak berkahwin dengan wanita lain selagi Khadijah hidup; perkahwinan yang lain berlaku selepas kewafatannya."),
"sira_239": ("Apakah nama bapa saudara Nabi ﷺ yang melindunginya tanpa memeluk Islam?", ["Abu Talib", "Hamzah", "Al-'Abbas", "Abu Lahab"], "Abu Talib, bapa kepada 'Ali, melindungi anak saudaranya daripada Quraisy sehingga kematiannya."),
"sira_240": ("Bapa saudara Nabi ﷺ yang manakah ditawan di Badar sebelum memeluk Islam?", ["Al-'Abbas bin 'Abd al-Muttalib", "Abu Talib", "Hamzah", "Az-Zubair bin 'Abd al-Muttalib"], "Al-'Abbas, bapa saudara Nabi ﷺ dan datuk kepada dinasti Abbasiyah, ditawan di Badar dan kemudian memeluk Islam."),
"sira_241": ("Apakah gelaran para sahabat yang menyertai peperangan Badar?", ["Ahli Badar (al-Badriyyun)", "Ansar", "Muhajirin", "Ahli Uhud"], "Para sahabat yang hadir di Badar dikenali sebagai al-Badriyyun, dan keutamaan itu khusus bagi mereka."),
"sira_242": ("Berapa bahagian daripada harta rampasan yang ditetapkan al-Quran untuk Allah, Rasul, kaum kerabat, anak yatim, orang miskin dan ibnu sabil?", ["Satu perlima", "Satu perdua", "Satu persepuluh", "Satu pertiga"], "«Ketahuilah bahawa apa sahaja yang kamu peroleh sebagai rampasan, maka satu perlima untuk Allah dan Rasul, kaum kerabat, anak yatim, orang miskin dan ibnu sabil.»"),
"sira_243": ("Ayat manakah, yang sering disebut bersama khutbah wida', yang mendasari kesamarataan manusia di sisi Allah?", ["«Sesungguhnya yang paling mulia antara kamu di sisi Allah ialah yang paling bertakwa»", "«Manusia daripada satu bapa»", "«Tiada seorang memikul dosa orang lain»", "«Tiada paksaan dalam agama»"], "«Wahai manusia, Kami menciptakan kamu daripada seorang lelaki dan seorang perempuan… sesungguhnya yang paling mulia antara kamu di sisi Allah ialah yang paling bertakwa.»"),
"sira_244": ("Berapa ramaikah yang menyertai Bai'ah 'Aqabah kedua, pertemuan menentukan dengan penduduk Yathrib?", ["Satu rombongan lebih tujuh puluh orang", "Tiga orang", "Sepuluh orang", "Lima ratus orang"], "Bai'ah 'Aqabah kedua menghimpunkan satu rombongan lebih tujuh puluh orang lelaki dan wanita Yathrib."),
"sira_245": ("Berapa orang naqib (ketua yang bertanggungjawab) yang dilantik Nabi ﷺ dalam kalangan penduduk Yathrib pada Bai'ah 'Aqabah?", ["Dua belas", "Empat", "Tujuh", "Dua puluh"], "Dua belas naqib dipilih untuk mewakili kumpulan rombongan Yathrib dan bertanggungjawab atas bai'ah mereka."),
"sira_246": ("Nama apakah yang diambil Madinah selepas Hijrah?", ["Madinatun Nabi, kota Nabi ﷺ", "Yathrib", "Taybah sahaja", "Al-Qura"], "Yathrib mengambil nama Madinatun Nabi, «kota Nabi ﷺ», yang diringkaskan menjadi al-Madinah."),
"sira_247": ("Khalifah manakah yang mengarahkan naskhah rasmi al-Quran disalin dan dihantar ke wilayah-wilayah?", ["'Uthman bin 'Affan", "Abu Bakar", "'Umar", "'Ali"], "Abu Bakar mengarahkan teks itu dikumpulkan; 'Uthman mengarahkan naskhah rasmi disalin dan dihantar ke kota-kota utama."),
"sira_248": ("Dalam bahasa apakah al-Quran diturunkan kepada Nabi ﷺ?", ["Bahasa Arab", "Bahasa Aramia", "Bahasa Parsi", "Bahasa Yunani"], "Al-Quran diturunkan dalam bahasa Arab yang jelas, bahasa kaum Nabi ﷺ sendiri."),
"sira_249": ("Sahabat manakah yang diutus Nabi ﷺ ke Bahrain, lalu pulang membawa ufti negeri itu?", ["Abu 'Ubaidah bin al-Jarrah", "Bilal", "Anas bin Malik", "Abu Zar"], "Abu 'Ubaidah bin al-Jarrah, yang digelar «orang kepercayaan umat ini», pulang dari Bahrain membawa uftinya."),
"sira_250": ("Peristiwa manakah yang menandakan permulaan takwim Islam?", ["Hijrah dari Makkah ke Madinah", "Kelahiran Nabi ﷺ", "Wahyu pertama", "Pembukaan Makkah"], "Takwim Hijrah bermula dengan tahun Hijrah, satu keputusan yang diambil pada zaman pemerintahan 'Umar."),
}
